import time
import threading
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, Dict, Optional, TypeVar, Generic

T = TypeVar('T')
K = TypeVar('K')
V = TypeVar('V')


class LRUCache(Generic[K, V]):
    """Thread-safe LRU cache with TTL expiry."""

    def __init__(self, max_size: int = 128, ttl: float = 60.0):
        self.max_size = max_size
        self.ttl = ttl
        self._data: OrderedDict[K, tuple[V, float]] = OrderedDict()
        self._lock = threading.RLock()

    def _is_expired(self, timestamp: float) -> bool:
        return (time.time() - timestamp) >= self.ttl

    def get(self, key: K) -> Optional[V]:
        with self._lock:
            if key not in self._data:
                return None
            value, timestamp = self._data[key]
            if self._is_expired(timestamp):
                del self._data[key]
                return None
            self._data.move_to_end(key)
            return value

    def put(self, key: K, value: V) -> None:
        with self._lock:
            if key in self._data:
                del self._data[key]
            self._data[key] = (value, time.time())
            self._data.move_to_end(key)
            while len(self._data) > self.max_size:
                self._data.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            return len(self._data)


def lru_cache(max_size: int = 128, ttl: float = 60.0):
    """Decorator factory for LRU caching with TTL expiry."""
    cache: LRUCache[Any, Any] = LRUCache(max_size=max_size, ttl=ttl)

    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            cached = cache.get(key)
            if cached is not None:
                return cached
            result = func(*args, **kwargs)
            cache.put(key, result)
            return result
        return wrapper
    return decorator

